python -c "
import torch
d = torch.load('/app/dataset.pt', map_location='cpu')
print(type(d))
if isinstance(d, (list, tuple)):
    for i, x in enumerate(d):
        print(i, type(x))
        if isinstance(x, torch.Tensor):
            print('  shape', tuple(x.shape), x.dtype, 'min', x.min().item(), 'max', x.max().item())
        elif isinstance(x, dict):
            for k, v in x.items():
                print('  ', k, type(v), tuple(v.shape) if isinstance(v, torch.Tensor) else '')
elif isinstance(d, torch.Tensor):
    print('shape', tuple(d.shape), d.dtype, 'min', d.min().item(), 'max', d.max().item())
"
